// CreateMany inserts multiple Category records in a single statement
func (r *CategoryRepository) CreateMany(ctx context.Context, inputs []*types.Category) ([]*types.Category, error) {
	if len(inputs) == 0 {
		return []*types.Category{}, nil
	}

	// Set audit fields

	// Build the batch INSERT in one pass over the fields. Each row records every
	// candidate column in the same order, with the value it binds or no value
	// when it leaves an optional column unset; buildBatchInsert inserts the
	// columns any row sets and writes DEFAULT for a row that leaves one unset.
	batch := make([][]batchInsertCell, 0, len(inputs))
	for _, input := range inputs {
		var row []batchInsertCell
		// Primary key: id. Schema-owned identities may supply a stable
		// UUID, matching CreateOne; a row without one takes the generated default.
		{
			cell := batchInsertCell{column: `id`}
			var zeroPrimaryKey types.IdentityUUID
			if primaryKey, ok := categoryUUIDValue(input.Id); ok && primaryKey != zeroPrimaryKey {
				cell.value, cell.set = primaryKey.ToUUID(), true
			}
			row = append(row, cell)
		}
		// Required field: name
		{
			cell := batchInsertCell{column: `"name"`, set: true}
			cell.value = input.Name
			row = append(row, cell)
		}
		// Optional field: budget
		{
			cell := batchInsertCell{column: `budget`}
			if input.Budget != nil {
				// Dereference pointer for database value (nullable complex types, enums, and scalars are pointers)
				cell.value = *input.Budget
				cell.set = true
			}
			row = append(row, cell)
		}
		// Optional field: budgetSince
		{
			cell := batchInsertCell{column: `budget_since`}
			if input.BudgetSince != nil {
				// Dereference pointer for database value (nullable complex types, enums, and scalars are pointers)
				cell.value = *input.BudgetSince
				cell.set = true
			}
			row = append(row, cell)
		}

		// Relationship foreign key columns, matching CreateOne
		// Relationship: parent (FK: parent_id)
		{
			cell := batchInsertCell{column: `parent_id`}
			var zeroId types.IdentityUUID
			if input.Parent != nil {
				if relID, ok := categoryUUIDValue(input.Parent.Id); ok && relID != zeroId {
					cell.value, cell.set = relID.ToUUID(), true
				}
			}
			row = append(row, cell)
		}
		batch = append(batch, row)
	}
	fieldNames, valuePlaceholders, values := buildBatchInsert(batch)

	// Build RETURNING clause with explicit column order matching scan order (using OrderedMembers for schema order)
	returningClauseMany := `"id", "name", "parent_id", "budget", "budget_since"`
	query := fmt.Sprintf(
		`INSERT INTO category (%s) VALUES %s RETURNING %s`,
		strings.Join(fieldNames, ", "),
		strings.Join(valuePlaceholders, ", "),
		returningClauseMany,
	)

	// Execute query
	var rows pgx.Rows
	var err error
	if r.tx != nil {
		rows, err = r.tx.Query(ctx, query, values...)
	} else {
		rows, err = r.db.pool.Query(ctx, query, values...)
	}
	if err != nil {
		return nil, fmt.Errorf("failed to execute batch insert: %w", err)
	}
	defer rows.Close()

	// Scan results
	results := []*types.Category{}
	for rows.Next() {
		result := &types.Category{}
		// Create temporary variables for nullable fields that need pointer scanning

		var tempBudget *types.GenericDecimal
		var tempBudgetSince pgtype.Date

		// Create temporary variables for relationship foreign keys (we don't store these in the struct)
		var tempRelParent *types.IdentityUUID

		// Scan all fields in schema order (matches DDL column order)
		err := rows.Scan(

			&result.Id,

			&result.Name,

			&tempRelParent,

			&tempBudget,

			&tempBudgetSince,
		)
		if err != nil {
			return nil, fmt.Errorf("failed to scan result: %w", err)
		}

		// Copy nullable fields when present

		if tempBudget != nil {
			// Nullable enum/scalar: typegen emits *Enum or *Scalar, assign pointer directly
			result.Budget = tempBudget
		}
		if tempBudgetSince.Valid {
			// Nullable date scalar: typegen emits *Scalar, take address of converted value
			tmpBudgetSince := types.TemporalDate(tempBudgetSince.Time.Format("2006-01-02"))
			result.BudgetSince = &tmpBudgetSince
		}

		// Set relationship IDs from scanned FK values
		if tempRelParent != nil {
			// Initialize pointer for optional relationship before setting ID
			result.Parent = &types.Category{Id: categoryUUIDPtr(*tempRelParent)}
		}
		results = append(results, result)
	}

	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("error iterating results: %w", err)
	}

	return results, nil
}

